	/**
	 * M-A1c: an independent island in the middle of a join chain is hoisted to the outer position so the native
	 * patterns around it flatten into one reorderable MultiJoin bag — a movement the algebra optimizer cannot do
	 * because it runs before islands exist.
	 */
	@Test
	public void independentIslandIsHoistedOutOfTheJoinChain() {
		String query = "SELECT ?s ?o ?n ?c WHERE { ?s <" + EX + "p> ?o . "
				+ "{ SELECT ?c WHERE { BIND(CONCAT(\"a\", \"b\") AS ?c) } } "
				+ "?s <" + EX + "q> ?n }";

		withIslands(() -> {
			List<String> hybrid = rows(query);
			assertThat(hybrid).containsExactlyInAnyOrderElementsOf(genericRows(query));
			assertThat(hybrid).hasSize(2);
			try (SailRepositoryConnection conn = repository.getConnection()) {
				String explain = conn.prepareTupleQuery(query).explain(Explanation.Level.Optimized).toString();
				// the outcome pin: both native patterns share one reorderable MultiJoin bag beside the island —
				// whether via the hoist (island compiled mid-chain) or the algebra order already placing it outside
				assertThat(explain).contains("MultiJoin(");
				assertThat(explain).contains("GenericEvalPlan");
			}
		});
	}

